                                    ))}
                                </div>
                            </div>

                            {/* Density Control */}
                            <div>
                                <label className="text-sm font-medium text-zinc-500 uppercase tracking-wider mb-3 block">Density</label>
                                <div className="flex gap-2 p-1 bg-white rounded-lg border border-zinc-200 inline-flex">
